function mcpItemCard(i, selected, sourceType) {
  const sel = selected ? theme.reverse(' > ') : '   '
  const name = selected ? theme.bold(i.name) : theme.dim(i.name)
  const desc = i.description || 'No description'
  const installCmd =
    sourceType === 'npm'
      ? `rolecraft mcp install npm:${i.name}`
      : `rolecraft mcp install gh:${i.name}`
  return [
    `${sel}${name}`,
    `   ${desc}`,
    `   ${sourceType === 'npm' ? '📦 npm' : '🟢 github'} · ${installCmd}`,
  ]
}
